const token=location.hash.slice(1)||sessionStorage.getItem('consoleToken')||'';sessionStorage.setItem('consoleToken',token);history.replaceState(null,'',location.pathname);document.querySelector('#demoLink').href='/demo#'+token;
const $=s=>document.querySelector(s),labels={demo_open:'在开发板打开演示',none:'不触发',gaze_calibrate:'开始标定',gaze_recalibrate:'重新标定',gaze_validate:'检查标定',gaze_pointer:'鼠标控制开关',gaze_dwell:'凝视点击开关',gaze_restore:'显示眼动窗口',visual:'仅观察',trajectory:'轨迹手势',release:'手势 / 眼动控制游戏',takeover:'电脑接管',page1:'查看人物 1',page2:'查看人物 2',register1:'登记人物 1',register2:'登记人物 2',single:'单人模式',dual:'双人模式',wake:'唤醒',confirm:'确定',cancel:'返回',next:'下一个',end:'结束回合',demo_next:'演示下一页',demo_previous:'演示上一页',demo_zoom_in:'演示放大',demo_zoom_out:'演示缩小',demo_focus:'演示聚焦开关',demo_snap:'演示吸附开关',demo_reset:'演示复位'};
const names={Open_Palm:'张开手掌',Victory:'V 手势',Thumb_Up:'拇指向上',Thumb_Down:'拇指向下',L_rev:'反 L',L_up:'上 L',L_rev_up:'上反 L'};
async function api(path,body){let r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'X-Console-Token':token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||r.status);return j}
async function action(body){try{let r=await api('action',body);pendingId=r.id;$('#feedback').textContent='操作已排队 #'+r.id+'，等待板端结果'}catch(e){$('#feedback').textContent=e.message}}
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action({action:b.dataset.action}));let initialized=false,latest=null,pendingId=null;
$('#save').onclick=async()=>{try{let bindings={};document.querySelectorAll('#mappings select').forEach(s=>bindings[s.dataset.key]=s.value);await api('bindings',{bindings,enabled:$('#enabled').checked});pendingId=null;$('#feedback').textContent='配对已保存到开发板'}catch(e){$('#feedback').textContent=e.message}};
function mapping(s){if(initialized)return;initialized=true;for(let [k,v]of Object.entries(s.bindings)){let l=document.createElement('label'),t=document.createElement('span'),select=document.createElement('select');let [kind,name]=k.split(':');t.textContent=(kind==='trajectory'?'轨迹 ':'')+(names[name]||name);select.dataset.key=k;for(let a of s.actions){let o=document.createElement('option');o.value=a;o.textContent=labels[a]||a;select.append(o)}select.value=v;l.append(t,select);$('#mappings').append(l)}$('#enabled').checked=s.enabled}
function draw(h){const cv=$('#trace'),c=cv.getContext('2d');c.clearRect(0,0,960,540);let ui=h.interaction_ui,reg=(h.registrations||[]).find(r=>r.slot===h.actor_slot&&r.tracking_state==='active'),ids=new Set((reg?.hands||[]).map(x=>x.track_id));let hands=(ui?.hands||[]).filter(x=>ids.has(x.track_id));let rank={REC:5,COUNTDOWN:4,ARMED:3,RESULT:2,IDLE:0};hands.sort((a,b)=>rank[b.state]-rank[a.state]);const hand=hands[0],state=hand?.state;document.querySelectorAll('.steps span').forEach(s=>s.classList.remove('active'));let ix={IDLE:0,ARMED:1,COUNTDOWN:1,REC:2,RESULT:3}[state];if(ix!==undefined)$('#s'+ix).classList.add('active');$('#strokeStatus').textContent=({IDLE:'握拳准备，然后伸出食指',ARMED:'已握拳 · 请伸出食指',COUNTDOWN:'保持伸指 · '+((hand?.countdown_remaining_ms||0)/1000).toFixed(1)+' 秒',REC:'正在记录轨迹 · 画完后握拳结束',RESULT:'轨迹完成'})[state]||'等待当前人物与手部';$('#strokeResult').textContent=hand?.classification?(hand.classification.accepted?hand.classification.label+' · '+Math.round(hand.classification.confidence*100)+'%':'置信度不足，请重画'):state==='RESULT'?'轨迹太短，请重画':'';
if(!ui)return;const [w,hh]=ui.source_size;for(let i=0;i<hands.length;i++){let a=hands[i],p=a.points||[];if(!p.length)continue;c.beginPath();p.forEach(([x,y],j)=>j?c.lineTo(x/w*960,y/hh*540):c.moveTo(x/w*960,y/hh*540));c.strokeStyle=i?'#779cf6':'#69e4c3';c.lineWidth=5;c.lineCap='round';c.lineJoin='round';c.shadowBlur=12;c.shadowColor=c.strokeStyle;c.stroke();c.shadowBlur=0;let [x,y]=p[p.length-1];c.beginPath();c.arc(x/w*960,y/hh*540,8,0,Math.PI*2);c.fillStyle=c.strokeStyle;c.fill()}}
async function poll(){try{let s=await api('state');latest=s;mapping(s);if(pendingId!==null){let done=s.events.find(e=>e.id===pendingId);if(done){$('#feedback').textContent=(labels[done.action]||done.action)+(done.ok?'：已完成':'：'+done.error);pendingId=null}}$('#connection').textContent=s.health.error?'模型未就绪':'模型在线 · '+(s.health.people_mode==='dual'?'双人':'单人');$('#dualControls').hidden=s.health.people_mode!=='dual';$('#personHint').textContent=s.health.error|| (s.health.people_mode==='dual'?'双人模式：依次登记人物及左右手，再切换查看。':'单人自动使用，无需登记。');$('#modeHint').textContent=s.health.error?'采集已停止，手势和眼动暂不可用':({0:'仅观察 / 电脑接管：模型运行，但不向游戏发送手势或眼动',1:'轨迹模式：握拳 → 伸指 → 倒计时 → 画轨迹',2:'游戏控制：标定有效后使用眼动与手势；点电脑接管可退出'})[s.health.effective_mode]||'正在切换模式';draw(s.health);$('#events').replaceChildren(...s.events.slice(-6).reverse().map(e=>{let p=document.createElement('div');p.textContent='#'+e.id+' '+(labels[e.action]||e.action)+' · '+(e.ok?'完成':e.error);return p}));}catch(e){$('#connection').textContent='连接断开：'+e.message;draw({})}finally{setTimeout(poll,150)}}poll();
let pad=$('#touchpad'),pointerNext=null,pointerJob=null;
function padPoint(e){let r=pad.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
pad.onpointermove=e=>{pointerNext=padPoint(e)};pad.onpointerleave=()=>{pointerNext=null};
setInterval(async()=>{if(pointerJob!==null&&latest?.events.some(e=>e.id===pointerJob))pointerJob=null;if(!pointerNext||pointerJob!==null)return;let xy=pointerNext;pointerNext=null;pointerJob=-1;try{pointerJob=(await api('action',{action:'pointer',...xy})).id}catch(e){pointerJob=null;$('#feedback').textContent=e.message}},150);
pad.onclick=e=>{pointerNext=null;pad.focus();action({action:'click',button:1,...padPoint(e)})};pad.oncontextmenu=e=>{e.preventDefault();pointerNext=null;pad.focus();action({action:'click',button:3,...padPoint(e)})};pad.onkeydown=e=>{let k={Enter:'Return',Escape:'Escape',ArrowUp:'Up',ArrowDown:'Down',ArrowLeft:'Left',ArrowRight:'Right',' ':'space',Tab:'Tab',F1:'F1'}[e.key]||(/^[0-9]$/.test(e.key)?e.key:null);if(k){e.preventDefault();if(!e.repeat)action({action:'key',key:k})}};
